import{d,C as a,o as g,c as p,a3 as e,E as s,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十一章","description":"《正易心法》第十一章——至于六子，即是阴阳：偏陂反侧是不平之名；六子象众人与万物，然破体炼之，纯体乃成。","frontmatter":{"title":"正易心法·第十一章","description":"《正易心法》第十一章——至于六子，即是阴阳：偏陂反侧是不平之名；六子象众人与万物，然破体炼之，纯体乃成。","category":"guide","aliases":["正易心法第十一章","偏陂反侧","破体炼之纯体乃成"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-11.md","filePath":"yijing/zheng-yi-xin-fa/chapter-11.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-11.md"},x=d({...c,setup(u){const o=[{id:"z11-01",label:"一、六子即是阴阳",showLabel:!0,sentences:[["至于六子，即是阴阳。",{text:"偏陂",glossary:"pianpo"},"反侧，不平之名。"]],note:["至于六子卦，也是阴阳——但偏斜不正、反侧不安，是不平衡状态的名称。（注意第十章与本章的对举：乾坤「即是阴阳」，六子「也是阴阳」——**同为阴阳，差别在纯与驳、平与不平**。六子不是另一种东西，而是同一种阴阳的偏态。）"]},{id:"z11-02",label:"二、一失健顺",showLabel:!0,sentences:[["乾健坤顺，阴阳之纯气也。一失健顺，则不平之气作，而六子生，观画象可知。"]],note:["乾的刚健、坤的柔顺，是阴阳的纯粹之气；一旦失去这刚健柔顺，不平之气便兴起，六子于是产生——观察卦画便可知晓。（六子各「偏」一处：震阳偏于下（躁）、巽阴伏于下（柔）、坎阳陷于中（险）、离阴附于中（虚）、艮阳止于上（滞）、兑阴浮于上（浮）。**没有一个是平衡的——这就是「不平之名」的具体含义。**）"]},{id:"z11-03",label:"三、庄子言阴阳错行",showLabel:!0,sentences:[["《庄子》曰：“阴阳",{text:"错行",glossary:"cuoxing"},"，天地大骇，有雷有霆，水中有火，",{text:"乃焚乃块",glossary:"naifennaikuai"},"。”正谓此耳。"]],note:["《庄子》说：「阴阳交错运行，天地大为震骇，于是有雷有霆，水中有火，乃至焚烧崩裂。」说的正是这个道理。（妙处在于六子几乎都在这句话里：有雷有霆＝震、水中有火＝坎离相激、乃焚＝离、乃块＝艮；巽（风）、兑（泽）虽未明点，也在其中。这是本书第二次引道家，且与第十章恰好成对——**《老子》「得一」说纯粹（乾坤），《庄子》「错行」说驳杂（六子）**。麻衣用道家的两个极端，夹住了全书的核心张力。）"]},{id:"z11-04",label:"四、六子非圣贤比",showLabel:!0,sentences:[["由是六子非圣贤比，特众人与万物而已。"]],note:["因此六子不能与圣贤相比，不过是众人与万物的象征而已。（这里有一个重要的平等性：**圣人（乾）、贤人（坤）、众人（六子）、万物（六子）都是阴阳的表现形式，只是纯粹程度不同。** 麻衣没说众人是「坏的」，也没说万物是「低等的」，只是说「偏陂，不平衡」——而不平衡，可以通过「炼」来改变。这与儒家「人皆可以为尧舜」暗合：**差别不在本质，在于是否经历了「炼」。**）"]},{id:"z11-05",label:"五、破体炼之",showLabel:!0,sentences:[["然由破体",{text:"炼",glossary:"lian"},"之，纯体乃成。"]],note:["然而经由破体的磨炼，纯体才能成就。（这是《正易心法》中唯一一句直接谈修养工夫的话，也是本章的分量所在：**不是叫你逃离偏陂，不是叫你假装自己是乾坤，而是说——正是在偏陂的磨炼中，纯体才能成就。破体不是悲剧，是必经之路。**「炼」字在陈抟一脉有内丹背景：矿石（驳）→ 冶炼 → 纯金（纯）；对应内丹的「炼精化气、炼气化神、炼神还虚」，即六子（坎离为核心）→ 坎离交媾 → 乾坤复原，也就是「后天返先天」。）"]}],i=[{id:"pianpo",term:"偏陂",pinyin:"piān pō",meaning:"偏斜不正。阴阳不纯，有所偏倚——六子各偏一处，故为「不平之名」。"},{id:"cuoxing",term:"错行",pinyin:"cuò xíng",meaning:"交错运行。语出《庄子》，描述阴阳失序的状态，对应六子。"},{id:"naifennaikuai",term:"乃焚乃块",pinyin:"nǎi fén nǎi kuài",meaning:"焚烧与崩裂。焚为离火之象，块为艮土崩裂之象。"},{id:"lian",term:"炼",pinyin:"liàn",meaning:"锻炼、提纯。「破体炼之，纯体乃成」——不逃离偏陂，而在偏陂中炼。"}];return(b,t)=>{const r=a("DaoTextReading"),l=a("DaoKeywordCards");return g(),p("div",null,[t[0]||(t[0]=e(`<h1 id="正易心法·第十一章" tabindex="-1">正易心法·第十一章 <a class="header-anchor" href="#正易心法·第十一章" aria-label="Permalink to &quot;正易心法·第十一章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章完成了<strong>九、十、十一章的三章论证链</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>论域</th><th>内容</th></tr></thead><tbody><tr><td>第九章</td><td><strong>生成论</strong></td><td>乾坤如何破体生六子</td></tr><tr><td>第十章</td><td><strong>本体论</strong></td><td>乾坤纯粹是圣贤的象征</td></tr><tr><td><strong>第十一章</strong></td><td><strong>工夫论</strong></td><td>六子偏陂是众人的状态，但可以<strong>炼而归纯</strong></td></tr></tbody></table><p><strong>本章的核心贡献是最后一句</strong>：</p><blockquote><p><strong>「然由破体炼之，纯体乃成。」</strong></p></blockquote><p>这是《正易心法》中<strong>唯一一句直接谈修养工夫的话</strong>——<strong>不是叫你逃离偏陂，不是叫你假装自己是乾坤，而是说：正是在偏陂的磨炼中，纯体才能成就。破体不是悲剧，是必经之路。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>为什么引《庄子》？</strong> 本书已两次引用道家，两次方向恰好相反：</p><table tabindex="0"><thead><tr><th>引用</th><th>描述</th><th>对应</th></tr></thead><tbody><tr><td>第十章引《老子》</td><td>纯粹（得一）</td><td><strong>乾坤</strong></td></tr><tr><td>第十一章引《庄子》</td><td>错杂（失序）</td><td><strong>六子</strong></td></tr></tbody></table><p><strong>麻衣用道家的两个极端，夹住了易学的核心张力：纯粹（乾坤）vs 驳杂（六子）、得一（老子）vs 错行（庄子）。</strong> 这不是随意引用，而是精心构建的思想对仗。</p><p><strong>「炼」字的内丹背景</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外丹：矿石（驳）→ 冶炼 → 纯金（纯）</span></span>
<span class="line"><span>内丹：后天身体（六子，驳杂）→ 炼精化气、炼气化神、炼神还虚 → 先天本性（乾坤，纯粹）</span></span>
<span class="line"><span>易学：六子（坎离为核心）→ 坎离交媾 → 乾坤复原（后天返先天）</span></span></code></pre></div><p><strong>麻衣在这里埋下了内丹修炼的种子</strong>——六子的「偏陂」，正是内丹修炼的原料。</p><p><strong>「众人与万物」的平等观</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>圣人（乾）、贤人（坤）、众人（六子）、万物（六子）</span></span>
<span class="line"><span>四者都是阴阳的表现形式，只是纯粹程度不同</span></span>
<span class="line"><span>差别不在本质，在于是否经历了「炼」</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先回顾九、十、十一章，看这个**「纯 → 破 → 炼 → 纯」**的完整循环；</li><li>把《庄子》那句引文对照六个子卦，看它是不是真的「六子都在里面」；</li><li>记住这一句：<strong>破体不是终点，是回归纯体的必经之路。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>偏陂反侧</strong>：六子各偏一处，皆「不平之名」。</li><li><strong>一失健顺</strong>：失去纯粹，不平之气作而六子生。</li><li><strong>庄子错行</strong>：六子尽在「阴阳错行」一句中。</li><li><strong>六子象众人万物</strong>：非圣贤，但非低等——只是「偏」。</li><li><strong>破体炼之，纯体乃成</strong>：全书唯一的工夫论。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),s(r,{colophon:"偏陂反侧 · 不平之名 · 阴阳错行 · 破体炼之",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十一章原文",sections:o,glossary:i}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"偏陂反侧",pinyin:["piān","pō"],meaning:"偏斜不正、翻转不安。六子各偏一处：震躁、巽柔、坎险、离虚、艮滞、兑浮——皆「不平之名」。"},{term:"不平之气作",pinyin:["bù","píng"],meaning:"失去纯粹健顺之后，不平衡的气兴起，六子由此而生。观卦画便可知晓。"},{term:"阴阳错行",pinyin:["cuò","xíng"],meaning:"《庄子》语。六子几乎都在这一句里：雷霆为震、水中有火为坎离、乃焚为离、乃块为艮。"},{term:"破体炼之",pinyin:["pò","tǐ"],meaning:"全书唯一的工夫论：不逃离偏陂，不假装是乾坤，而是在偏陂的磨炼中成就纯体。"},{term:"炼（内丹背景）",pinyin:["liàn"],meaning:"矿石（驳）→ 纯金（纯）；内丹「炼精化气、炼气化神、炼神还虚」即六子坎离交媾、后天返先天。"}]}),t[3]||(t[3]=e(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章完成九、十、十一章的三章论证链：<strong>生成论（九）→ 本体论（十）→ 工夫论（十一）</strong>。</p><p><strong>核心贡献是最后一句：「然由破体炼之，纯体乃成。」</strong> 这是全书唯一一句直接谈修养工夫的话。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>为什么引《庄子》？</strong> 两次引道家的方向恰好相反：</p><table tabindex="0"><thead><tr><th>引用</th><th>描述</th><th>对应</th></tr></thead><tbody><tr><td>《老子》「得一」</td><td>纯粹</td><td>乾坤</td></tr><tr><td>《庄子》「错行」</td><td>错杂</td><td>六子</td></tr></tbody></table><p><strong>麻衣用道家的两个极端，夹住了易学的核心张力</strong>——这不是随意引用，而是精心构建的思想对仗。</p><p><strong>「炼」字的内丹背景</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外丹：矿石（驳）→ 冶炼 → 纯金（纯）</span></span>
<span class="line"><span>内丹：后天身体（六子，驳杂）→ 炼精化气、炼气化神、炼神还虚 → 先天本性（乾坤，纯粹）</span></span>
<span class="line"><span>易学：六子（坎离为核心）→ 坎离交媾 → 乾坤复原（后天返先天）</span></span></code></pre></div><p><strong>「众人与万物」的平等观</strong>：圣人（乾）、贤人（坤）、众人（六子）、万物（六子）<strong>都是阴阳的表现形式，只是纯粹程度不同</strong>——差别不在本质，在于是否经历了「炼」。</p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把《庄子》那句对照六个子卦看一遍（雷霆、水中火、焚、块）；</li><li>记住这个「三步」：<strong>找到落处（在六子的哪个偏陂）→ 在偏中炼 → 纯体乃成</strong>；</li><li>也记住：<strong>这里的「炼」不是逃离，是就地取材。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>至于六子卦，也是阴阳——但偏斜不正、反侧不安，是不平衡状态的名称。</p><p>乾的刚健、坤的柔顺，是阴阳的纯粹之气；一旦失去这刚健柔顺，不平之气便兴起，六子于是产生——观察卦画便可知晓。</p><p>《庄子》说：「阴阳交错运行，天地大为震骇，于是有雷有霆，水中有火，乃至焚烧崩裂。」说的正是这个道理。</p><p>因此六子不能与圣贤相比，不过是众人与万物的象征而已。</p><p>然而经由破体的磨炼，纯体才能成就。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十一章把第九章的「破体」翻了个面——<strong>破体不只是生成万物，也是修炼的原料；「炼」这个字，把「偏」从缺点变成了材料。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「偏陂反侧，不平之名」</strong>——六个子卦，六个不平衡。<strong>我身上最像哪一卦？</strong> 是震（躁动，一触即发），还是艮（凝滞，固执不化）？</li><li><strong>「一失健顺」</strong>——六子之所以生，是因为「失去了纯粹」。<strong>这个「失」不是坠落，是流动</strong>：气一旦动起来，就不可能一直纯粹。<strong>这不正像人吗——一生下来就已经在偏里了。</strong></li><li><strong>「炼」这个字</strong>——这是全书唯一一句工夫论，分量极重。<strong>它把「偏」从罪变成了资粮：不逃离偏陂，在偏陂里炼。</strong> 这与「逃避式修行」是完全相反的路径。</li><li><strong>平等观</strong>——麻衣没有说众人是「坏的」。<strong>差别不在本质，在是否经历了「炼」。</strong> 这句话让我松了一口气，也让我更警醒。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>坎离是六子中最特殊的两个——内丹的核心正是「坎离交媾」（取坎中之阳，填离中之阴），坎离合而复原为乾坤。这个「炼」的具体机制，与第九章的「破体」是否互为镜像？</strong> 我的想法是：<strong>正是镜像</strong>——破体是「一阳入坤成坎、一阴入乾成离」，把纯体分开；而「炼」（取坎填离）是把分开的阳阴再换回去，复归纯体。<strong>一破一炼，同一条路，两个方向。</strong> 这也解释了为什么内丹独重坎离：<strong>它们离乾坤最近——只差中和爻的一步之隔。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 破体（本章是它的工夫论面）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-10">第十章 · 即是阴阳</a> — 「天得一以清」（本章与之成「纯粹／错杂」的对仗）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-21">第二十一章</a> — 「六子假合，无有定实」：本章「炼」的进一步发展</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「阴阳错行」与八卦物象的对应</li></ul>`,25))])}}});export{y as __pageData,x as default};
